    fun resolve(profile:RuleProfile,terrain:String,d8:Int,d12:Int):ClassicWildernessEncounterResult? {
        if(profile!=RuleProfile.OSE_CLASSIC_FANTASY || d8 !in 1..8 || d12 !in 1..12) return null
        val route=primary[terrain]?.get(d8-1) ?: return null
        val content=tables[route.first]?.get(route.second)?.get(d12-1) ?: return null
        return ClassicWildernessEncounterResult(terrain,d8,d12,route.first,route.second,content)
    }
